def is_balanced(s: str) -> bool:
    pairs = {'(': ')', '[': ']', '{': '}'}
    closing = set(pairs.values())
    stack = []
    for ch in s:
        if ch in pairs:
            stack.append(pairs[ch])
        elif ch in closing:
            if not stack or stack.pop() != ch:
                return False
    return not stack
